import type { BaziAlgorithmResult, BirthInfo as BaziBirthInfo } from '@aceworld/bazi-algorithm';
import type { ZiweiChart } from '@aceworld/ziwei-algorithm';
export type ReadingDomain = 'personality' | 'career' | 'wealth' | 'relationship' | 'family' | 'health' | 'wellbeing' | 'timing';
export type EvidenceSystem = 'bazi' | 'ziwei' | 'cross';
export type EvidenceLayer = 'foundation' | 'palace' | 'combination' | 'support' | 'transformation' | 'structure' | 'timing';
export type EvidencePolarity = 'opportunity' | 'risk' | 'mixed' | 'neutral';
export type Confidence = 'high' | 'medium' | 'low';
export interface InterpretationEvidence {
    id: string;
    system: EvidenceSystem;
    domain: ReadingDomain;
    layer: EvidenceLayer;
    title: string;
    statement: string;
    basis: string[];
    polarity: EvidencePolarity;
    weight: number;
    confidence: Confidence;
    sourceUrl?: string;
}
export interface DomainReading {
    domain: ReadingDomain;
    score: number;
    confidence: Confidence;
    summary: string;
    opportunities: string[];
    risks: string[];
    evidenceIds: string[];
}
export interface ChartInterpretation {
    method: 'evidence-chain-v1';
    methodology: string[];
    evidence: InterpretationEvidence[];
    domains: DomainReading[];
    cautions: string[];
}
export interface CombinedChartResult {
    schemaVersion: 'bazi-ziwei-chart.v2';
    engineVersions: {
        bazi: string;
        ziwei: string;
        interpretation: string;
    };
    calculationContext: {
        currentYear: number;
    };
    birthInfo: BaziBirthInfo;
    bazi: BaziAlgorithmResult;
    ziwei: ZiweiChart;
    interpretation: ChartInterpretation;
}
export type CombinedBirthInfo = BaziBirthInfo;
